return ['domain'=>'page-builder-sandwich','plural-forms'=>'nplurals=1; plural=0;','language'=>'ms_MY','project-id-version'=>'page-builder-sandwich','pot-creation-date'=>'2026-09-26T16:59:17+00:00','po-revision-date'=>'2026-09-26T16:59:17+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Page Builder Sandwich'=>'Page Builder Sandwich','https://zinndigital.com/wordpress-plugins/page-builder-sandwich'=>'https://zinndigital.com/wordpress-plugins/page-builder-sandwich','The foundation release of the rebuilt Page Builder Sandwich: a settings and About screen, a footprint-free front-end output layer, and one sample content block.'=>'Keluaran asas Page Builder Sandwich yang dibina semula: tetapan dan skrin Perihal, lapisan output bahagian hadapan bebas jejak, dan satu blok kandungan sampel.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','AI providers'=>'Penyedia AI','The makers of ChatGPT. A good all-rounder.'=>'Pembuat ChatGPT. Pilihan pelbagai guna yang baik.','The makers of Claude. Strong at writing and careful reasoning.'=>'Pembuat Claude. Handal dalam penulisan dan penaakulan yang teliti.','Google\'s Gemini models. Fast and inexpensive.'=>'Model Gemini daripada Google. Pantas dan murah.','A European AI company with fast, inexpensive models.'=>'Sebuah syarikat AI Eropah dengan model yang pantas dan murah.','Low-cost models that are good at writing and code.'=>'Model kos rendah yang bagus dalam penulisan dan kod.','One key for models from many different providers.'=>'Satu kunci untuk model daripada pelbagai pembekal yang berbeza.','Any service that works like OpenAI\'s API, including a model running on your own computer or server.'=>'Sebarang perkhidmatan yang berfungsi seperti API OpenAI, termasuk model yang berjalan pada komputer atau pelayan anda sendiri.','General (used when nothing more specific is set)'=>'Umum (digunakan apabila tiada yang lebih khusus ditetapkan)','Writing and rewriting'=>'Penulisan dan penulisan semula','Translation'=>'Terjemahan','Code and CSS'=>'Kod dan CSS','Sorry, you are not allowed to access this page.'=>'Maaf, anda tidak dibenarkan mengakses halaman ini.','These settings are shared by every plugin that uses them: %s.'=>'Tetapan ini dikongsi oleh setiap plugin yang menggunakannya: %s.','Your keys are encrypted in this site\'s database and are only ever sent to the provider you chose — never to us.'=>'Kekunci anda disulitkan dalam pangkalan data tapak ini dan hanya dihantar kepada pembekal yang anda pilih — tidak pernah kepada kami.','Step 1 of 2: choose an AI provider'=>'Langkah 1 daripada 2: pilih pembekal AI','You bring your own key, so you pay the provider directly for what you use. Not sure? Any of these works well; you can add more later.'=>'Anda menggunakan kunci anda sendiri, jadi anda membayar terus kepada pembekal untuk apa yang anda guna. Tidak pasti? Mana-mana daripada ini berfungsi dengan baik; anda boleh menambah lagi kemudian.','Next'=>'Seterusnya','Step 2 of 2: connect %s'=>'Langkah 2 daripada 2: sambungkan %s','Enter the address of your OpenAI-compatible service, ending in /v1. A key is only needed if the service asks for one.'=>'Masukkan alamat perkhidmatan yang serasi dengan OpenAI anda, diakhiri dengan /v1. Kunci hanya diperlukan jika perkhidmatan itu memintanya.','Open %s and sign in (or create a free account).'=>'Buka %s dan log masuk (atau buat akaun percuma).','the %s API keys page'=>'halaman kekunci API %s','Create a new key and copy it.'=>'Cipta kekunci baharu dan salinnya.','Paste it below and press "Save and test". We send one tiny request to check it works.'=>'Tampal di bawah dan tekan "Simpan dan uji". Kami menghantar satu permintaan kecil untuk mengesahkan ia berfungsi.','Most providers need a little credit on the account before a key works: %s.'=>'Kebanyakan pembekal memerlukan sedikit kredit pada akaun sebelum kunci berfungsi: %s.','add credit'=>'tambah kredit','← Choose a different provider'=>'← Pilih pembekal yang lain','Address'=>'Alamat','Saved key ends in …%s — paste a new one to replace it'=>'Kunci yang disimpan berakhir dengan …%s — tampal kunci baharu untuk menggantikannya','Key (optional)'=>'Kunci (pilihan)','API key'=>'Kunci API','Save and test'=>'Simpan dan uji','Providers'=>'Penyedia','Provider'=>'Pembekal','Status'=>'Status','Key'=>'Kunci','Get a key'=>'Dapatkan kekunci','Test'=>'Uji','Remove'=>'Buang','Saved by a newer plugin version: update this plugin, or enter the key again.'=>'Disimpan oleh versi plugin yang lebih baharu: kemas kini plugin ini, atau masukkan semula kunci tersebut.','The saved key can no longer be opened (the site\'s security keys changed). Enter it again.'=>'Kunci yang disimpan tidak lagi boleh dibuka (kunci keselamatan tapak telah berubah). Masukkannya sekali lagi.','Not connected'=>'Tidak bersambung','Connected — last test passed %s'=>'Disambungkan — ujian terakhir lulus %s','Last test failed: %s'=>'Ujian terakhir gagal: %s','Connected — not tested yet'=>'Disambungkan — belum diuji','Which model to use'=>'Model mana yang hendak digunakan','★ marks our recommendation for that task. The list includes every model your key can use, read live from the provider.'=>'★ menandakan cadangan kami untuk tugas tersebut. Senarai ini merangkumi setiap model yang boleh digunakan oleh kunci anda, dibaca secara langsung daripada pembekal.','— Recommended for the provider —'=>'— Disyorkan untuk penyedia —','Save models'=>'Simpan model','Refresh the model lists from the providers'=>'Muat semula senarai model daripada pembekal','best quality'=>'kualiti terbaik','lowest cost'=>'kos terendah','fastest'=>'pantas','Add a model yourself'=>'Tambah model sendiri','A model came out today? Paste its exact name to use it straight away.'=>'Model baharu telah keluar hari ini? Tampal nama tepatnya untuk menggunakannya serta-merta.','Model name'=>'Nama model','Add model'=>'Tambah model','Recommended models list'=>'Senarai model yang disyorkan','The recommended models list could not be verified, so no recommendations are shown. Reinstall the plugin, or turn on daily updates below.'=>'Senarai model yang disyorkan tidak dapat disahkan, jadi tiada cadangan yang ditunjukkan. Pasang semula palam masuk, atau dayakan kemas kini harian di bawah.','The list in use was published on %s. Each plugin update brings a fresh one.'=>'Senarai yang digunakan telah diterbitkan pada %s. Setiap kemas kini palam masuk membawa yang baharu.','Also check Zinn Digital® once a day for an updated list.'=>'Sila semak juga Zinn Digital® sekali sehari untuk senarai yang dikemas kini.','Only a plain download request is sent: no key, no site address, nothing about your content. The list is signed, and a list that fails the signature check is ignored.'=>'Hanya permintaan muat turun biasa yang dihantar: tiada kunci, tiada alamat tapak, tiada apa-apa tentang kandungan anda. Senarai tersebut ditandatangani, dan senarai yang gagal dalam semakan tandatangan akan diabaikan.','Last checked %1$s: %2$s.'=>'Semakan terakhir %1$s: %2$s.','Save, and check now if turned on'=>'Simpan, dan semak sekarang jika dihidupkan','a newer list was installed'=>'senarai yang lebih baharu telah dipasang','already up to date'=>'sudah dikemas kini','the download failed the signature check and was ignored'=>'muat turun gagal dalam pemeriksaan tandatangan dan diabaikan','Zinn Digital® could not be reached; the current list stays in use'=>'Zinn Digital® tidak dapat dihubungi; senarai semasa terus digunakan','turned off'=>'dipadamkan','Open'=>'Buka','Check their status page'=>'Semak halaman status mereka','Open your billing page'=>'Buka halaman pengebilan anda','Open your API keys page'=>'Buka halaman kekunci API anda','Open the AI settings'=>'Buka tetapan AI','Sorry, you are not allowed to do that.'=>'Maaf, anda tidak dibenarkan berbuat demikian.','Unknown provider.'=>'Penyedia tidak diketahui.','Enter the address of your service, for example http://localhost:11434/v1.'=>'Masukkan alamat perkhidmatan anda, sebagai contoh http://localhost:11434/v1.','That does not look like an API key. Copy it again, without spaces.'=>'Itu tidak kelihatan seperti kunci API. Salin sekali lagi, tanpa ruang.','Paste your API key first.'=>'Tampal kunci API anda terlebih dahulu.','Key removed.'=>'Kunci dialih keluar.','Models saved.'=>'Model disimpan.','Enter the model\'s exact name, for example as the provider\'s documentation writes it.'=>'Masukkan nama tepat model tersebut, contohnya seperti yang ditulis dalam dokumentasi pembekal.','Added %s. Choose it under "Which model to use".'=>'%s telah ditambah. Pilihnya di bawah "Model yang hendak digunakan".','Model removed.'=>'Model dialih keluar.','Daily updates are off. The list that came with the plugin is used.'=>'Kemas kini harian dimatikan. Senarai yang disertakan bersama palam masuk itu digunakan.','Checked: %s.'=>'Disemak: %s.','Model lists refreshed.'=>'Senarai model telah dimuat semula.','Your AI key was saved by a newer version of one of your plugins. Update this plugin, or enter the key again in the AI settings.'=>'Kunci AI anda telah disimpan oleh versi yang lebih baharu daripada salah satu palam masuk anda. Kemas kini palam masuk ini, atau masukkan semula kunci dalam tetapan AI.','Your saved AI key can no longer be opened (the site\'s security keys changed). Enter it again in the AI settings.'=>'Kunci AI anda yang disimpan tidak lagi boleh dibuka (kunci keselamatan tapak telah berubah). Masukkan ia semula dalam tetapan AI.','AI is not set up yet. Add a key for an AI provider in the AI settings.'=>'AI belum disediakan. Tambah kunci untuk pembekal AI dalam tetapan AI.','No model is chosen for this task. Pick one in the AI settings.'=>'Tiada model dipilih untuk tugas ini. Pilih satu dalam tetapan AI.','That AI provider is not supported by this version of the plugin.'=>'Penyedia AI tersebut tidak disokong oleh versi plugin ini.','This site could not reach your AI service. Check that it is running and that its address is reachable from your web server (a service on your own computer is not reachable from a hosted site).'=>'Tapak ini tidak boleh mencapai perkhidmatan AI anda. Semak sama ada ia sedang berjalan dan alamatnya boleh dicapai dari pelayan web anda (perkhidmatan pada komputer anda sendiri tidak boleh dicapai dari tapak yang dihoskan).','This site could not reach %s. Check their status page; if they are up, your host may be blocking outgoing connections, or the address is wrong.'=>'Tapak ini tidak dapat menghubungi %s. Semak halaman status mereka; jika ia aktif, hos anda mungkin menyekat sambungan keluar, atau alamat tersebut salah.','%s says your account has no credit or quota left. Add credit or raise your limit in your account with them, then try again.'=>'%s menyatakan akaun anda tiada baki kredit atau kuota yang tinggal. Tambah kredit atau naikkan had anda dalam akaun anda bersama mereka, kemudian cuba lagi.','%s did not accept your key. It may be mistyped, revoked or expired. Create a new key and paste it here.'=>'%s tidak menerima kunci anda. Kunci tersebut mungkin tersilap taip, telah ditarik balik, atau telah tamat tempoh. Buat kunci baharu dan tampalkannya di sini.','%s refused this request for your key. The key may not have access to this model or feature, or your account needs verifying.'=>'%s menolak permintaan ini untuk kunci anda. Kunci tersebut mungkin tidak mempunyai akses kepada model atau ciri ini, atau akaun anda perlu disahkan.','The model "%1$s" is not available from %2$s for your key. Choose another model in the AI settings.'=>'Model "%1$s" tidak tersedia daripada %2$s untuk kekunci anda. Pilih model lain dalam tetapan AI.','Your %2$s plan does not include the model "%1$s". Choose another model in the AI settings, or upgrade your plan with them.'=>'Pelan %2$s anda tidak merangkumi model "%1$s". Pilih model lain dalam tetapan AI, atau tingkatkan pelan anda bersama mereka.','%s is limiting how fast your key can send requests. Wait a minute and try again, or raise your rate limit with them.'=>'%s mengehadkan kelajuan kunci anda menghantar permintaan. Tunggu seminit dan cuba lagi, atau tingkatkan had kadar anda dengan mereka.','%s is having problems right now (an outage or overload on their side). Nothing is wrong with your settings. Try again shortly.'=>'%s sedang mengalami masalah sekarang (gangguan atau lebih beban pada pihak mereka). Tiada masalah dengan tetapan anda. Cuba sebentar lagi.','The AI request failed for a reason we could not identify. Try again; if it keeps happening, contact support with the details below.'=>'Permintaan AI gagal atas sebab yang tidak dapat kami kenal pasti. Cuba lagi; jika ia terus berlaku, hubungi sokongan dengan butiran di bawah.','The AI provider answered in a form this plugin could not read. Try again; if it keeps happening, choose another model or contact support.'=>'Pembekal AI membalas dalam bentuk yang tidak boleh dibaca oleh palam ini. Cuba lagi; jika ia terus berlaku, pilih model lain atau hubungi sokongan.','Custom (OpenAI-compatible)'=>'Tersuai (serasi dengan OpenAI)','Save a key for this provider first.'=>'Simpan kunci untuk pembekal ini dahulu.','Your key works, but the provider lists no text model for it. Add a model yourself below.'=>'Kunci anda berfungsi, tetapi pembekal tidak menyenaraikan model teks untuknya. Tambah model sendiri di bawah.','Connected. %1$s answered using %2$s. Your AI features are ready to use.'=>'Bersambung. %1$s menjawab menggunakan %2$s. Ciri AI anda sedia untuk digunakan.','Your user role is not allowed to use AI on this site. Ask an administrator.'=>'Peranan pengguna anda tidak dibenarkan menggunakan AI di tapak web ini. Sila tanya pentadbir.','This site has reached its monthly AI spending limit. An administrator can raise it in the AI settings.'=>'Tapak ini telah mencapai had perbelanjaan AI bulanan. Pentadbir boleh meningkatkannya dalam tetapan AI.','This site has reached its monthly limit of AI requests. An administrator can raise it in the AI settings.'=>'Tapak web ini telah mencapai had bulanan untuk permintaan AI. Pentadbir boleh menaikkannya dalam tetapan AI.','Usage and cost'=>'Penggunaan dan kos','The log, limits and role permissions apply to AI used through: %s.'=>'Log, had tangan dan kebenaran peranan terpakai untuk AI yang digunakan melalui: %s.','Costs are approximate, worked out from published prices; a model with no known price counts as zero.'=>'Kos adalah anggaran, dikira daripada harga yang diterbitkan; model yang tiada harga yang diketahui dikira sebagai sifar.','This month: %1$s requests, about %2$s.'=>'Bulan ini: %1$s permintaan, kira-kira %2$s.','When'=>'Bila','Who'=>'Siapa','Used for'=>'Digunakan untuk','Model'=>'Model','Tokens in / out'=>'Token masuk / keluar','About'=>'Mengenai','Result'=>'Keputusan','No AI requests have been made yet.'=>'Tiada permintaan AI telah dibuat lagi.','Done'=>'Selesai','Limits and permissions'=>'Had dan kebenaran','Monthly spending limit (US dollars)'=>'Had bulanan (Dolar US)','Leave empty for no limit. AI stops for the rest of the month once the approximate cost reaches it.'=>'Biarkan kosong untuk tiada had. AI akan berhenti untuk baki bulan tersebut sebaik sahaja anggaran kos mencecahnya.','Monthly request limit'=>'Had درخواست bulanan','Leave empty for no limit.'=>'Biarkan kosong untuk tiada had.','Who may use AI'=>'Siapa yang boleh menggunakan AI','Tick none to let everyone who can use the plugin\'s features use AI. Administrators can always use it.'=>'Tanda tiada untuk membenarkan semua orang yang boleh menggunakan ciri-ciri plugin untuk menggunakan AI. Pentadbir sentiasa boleh menggunakannya.','Save limits and permissions'=>'Simpan had dan kebenaran','Limits and permissions saved.'=>'Had dan kebenaran disimpan.','Security error, please refresh the page and try again.'=>'Ralat keselamatan, sila muat semula halaman dan cuba lagi.','Missing newsletter settings. Please contact the admin.'=>'Tetapan surat berita hilang. Sila hubungi pentadbir.','Invalid newsletter settings. Please contact the admin.'=>'Tetapan surat berita tidak sah. Sila hubungi pentadbir.','Invalid email address.'=>'Alamat e-mel tidak sah.','Too many attempts. Please try again in a few minutes.'=>'Terlalu banyak percubaan. Sila cuba lagi dalam beberapa minit.','Something went wrong. Please contact the admin.'=>'Ada yang tidak kena. Sila hubungi pentadbir.','Map'=>'Peta','Background video'=>'Video latar belakang','%1$s: %2$d font files stored, stylesheet %3$s'=>'%1$s: %2$d fail fon disimpan, helaian gaya %3$s','That family is not stored.'=>'Keluarga tersebut tidak disimpan.','Removed.'=>'Telah dialih keluar.','That is not a valid font family name.'=>'Itu bukan nama keluarga fon yang sah.','Google Fonts did not return that family. Check the name and try again.'=>'Google Fonts tidak memulihkan fon tersebut. Sila semak nama itu dan cuba lagi.','The font files could not be downloaded or saved. Check that the uploads folder is writable.'=>'Fail fon tidak dapat dimuat turun atau disimpan. Semak sama ada folder muat naik boleh ditulis.','The font stylesheet could not be saved. Check that the uploads folder is writable.'=>'Stylesheet fon tidak boleh disimpan. Semak sama ada folder muat naik boleh ditulis.','The admin screen\'s scripts are missing from this copy of the plugin. Reinstall it from a released package.'=>'Skrip skrin pentadbir hilang daripada salinan plugin ini. Pasang semula daripada pakej yang dikeluarkan.','This screen needs JavaScript.'=>'Skrin ini memerlukan JavaScript.','Languages'=>'Bahasa','Upgrade'=>'Naik Taraf','Pricing'=>'Harga','Start Trial'=>'Mula Percubaan','Account'=>'Akaun','Contact Us'=>'Hubungi Kami','Affiliation'=>'Gabungan','the kind of softwarePlugin'=>'Pelayan Palam','greetingHey %s,'=>'Hai %s,','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info. This will help us make the %s more compatible with your site and better at doing what you need it to.'=>'Pilih untuk menerima pemberitahuan e-mel untuk kemas kini keselamatan & ciri, kandungan pendidikan dan tawaran sekali-sekala, serta untuk berkongsi beberapa maklumat asas persekitaran WordPress. Ini akan membantu kami menjadikan %s lebih serasi dengan tapak anda dan lebih baik dalam melakukan apa yang anda perlukan.','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info.'=>'Pilih untuk menerima pemberitahuan e-mel untuk kemas kini keselamatan & ciri, kandungan pendidikan, dan tawaran sekali-sekala, serta untuk berkongsi beberapa maklumat asas persekitaran WordPress.','If you skip this, that\'s okay! %1$s will still work just fine.'=>'Jika anda melangkau ini, tidak mengapa! %1$s akan tetap berfungsi dengan baik.','Allow & Continue'=>'Benarkan & Teruskan','verbSkip'=>'Langkau','Skipping, please wait'=>'Melangkau, sila tunggu','Continue'=>'Teruskan','Please wait'=>'Sila tunggu','as activating pluginActivating'=>'Sedang diaktifkan','This will allow %s to'=>'Ini akan membolehkan %s untuk','Privacy Policy'=>'Dasar Privasi','Terms of Service'=>'Terma Perkhidmatan','License Agreement'=>'Perjanjian Lesen','Have a license key?'=>'Ada kunci lesen?','Activate License'=>'Aktifkan Lesen','View Basic Profile Info'=>'Lihat Maklumat Profil Asas','Your WordPress user\'s: first & last name, and email address'=>'Pengguna WordPress anda: nama pertama & terakhir, dan alamat e-mel','View Basic Website Info'=>'Lihat Maklumat Asas Laman Web','Homepage URL & title, WP & PHP versions, and site language'=>'URL & tajuk Laman Utama, versi WP & PHP, dan bahasa tapak','View Basic %s Info'=>'Lihat Maklumat Asas %s','Current %s & SDK versions, and if active or uninstalled'=>'Versi %s & SDK semasa, dan sama ada aktif atau dinyahpasang','Newsletter'=>'Surat Berita','Updates, announcements, marketing, no spam'=>'Kemas kini, pengumuman, pemasaran, tiada spam','View Diagnostic Info'=>'Lihat Maklumat Diagnostik','WordPress & PHP versions, site language & title'=>'Versi WordPress & PHP, bahasa & tajuk laman','View Plugins & Themes List'=>'Lihat Senarai Palam & Tema','Names, slugs, versions, and if active or not'=>'Nama, slug, versi, dan sama ada aktif atau tidak','optional'=>'pilihan','Never miss an important update'=>'Jangan lepaskan kemas kini penting','We have introduced this opt-in so you never miss an important update and help us make the %s more compatible with your site and better at doing what you need it to.'=>'Kami telah memperkenalkan pilihan ini supaya anda tidak terlepas sebarang kemas kini penting dan membantu kami menjadikan %s lebih serasi dengan tapak anda serta lebih baik dalam melakukan perkara yang anda perlukan.','Thank you for updating to %1$s v%2$s!'=>'Terima kasih kerana mengemas kini kepada %1$s v%2$s!','The prefix must be 1 to 8 lowercase letters or digits, start with a letter, and must not name the plugin.'=>'Awalan mestilah terdiri daripada 1 hingga 8 huruf kecil atau digit, bermula dengan huruf, dan tidak boleh menamakan plugin tersebut.','You are not allowed to edit this item.'=>'Anda tidak dibenarkan mengedit item ini.','You are not allowed to do this.'=>'Anda tidak dibenarkan melakukan ini.','Safe mode was turned off because it no longer matches your login. Reload the page.'=>'Mod selamat dimatikan kerana ia tidak lagi sepadan dengan log masuk anda. Muat semula halaman.','Only an administrator can use safe mode.'=>'Hanya pentadbir boleh menggunakan mod selamat.','Safe mode needs a normal browser login.'=>'Mod selamat memerlukan log masuk pelayar biasa.','Safe mode could not be set up.'=>'Mod selamat tidak dapat disediakan.','Safe mode needs write access to the wp-content/mu-plugins folder.'=>'Mod selamat memerlukan akses tulis ke folder wp-content/mu-plugins.','Safe mode could not write to the wp-content/mu-plugins folder.'=>'Mod selamat tidak dapat menulis ke folder wp-content/mu-plugins.','Sandwich Studio'=>'Studio Sandwich','That page does not exist, or it has been deleted.'=>'Halaman tersebut tidak wujud, atau ia telah dipadamkan.','Sorry, you are not allowed to edit this item in Sandwich Studio.'=>'Maaf, anda tidak dibenarkan mengedit item ini dalam Sandwich Studio.','Sandwich Studio is not built. Reinstall the plugin.'=>'Sandwich Studio tidak dibina. Pasang semula palam masuk.','Add title'=>'Tambah tajuk','Type / to choose a block'=>'Ketik / untuk memilih blok','Loading Sandwich Studio…'=>'Memuatkan Sandwich Studio…','Sandwich Studio needs JavaScript. Use the normal editor instead.'=>'Sandwich Studio memerlukan JavaScript. Sila gunakan editor biasa.','Edit “%s” with Sandwich Studio'=>'Sunting “%s” dengan Sandwich Studio','Edit with Sandwich Studio'=>'Sunting dengan Sandwich Studio','Blank canvas'=>'Kanvas kosong','A migration step is running right now. Try again in a minute.'=>'Satu langkah migrasi sedang berjalan sekarang. Cuba lagi dalam masa seminit.','Thank you for subscribing!'=>'Terima kasih kerana melanggan!','Something went wrong. Please contact the administrator.'=>'Ada yang tidak kena. Sila hubungi pentadbir.','Years'=>'Tahun','Months'=>'Bulan','Weeks'=>'Minggu','Days'=>'Hari','Hours'=>'Jam','Minutes'=>'Minit','Seconds'=>'Saat','Go to slide %d'=>'Pergi ke slaid %d','You\'re already subscribed to our newsletter'=>'Anda sudah melanggan surat berita kami','Email address is already subscribed.'=>'Alamat e-mel sudah dilanggan.','MailPoet plugin not found. Please contact the admin.'=>'Plugin MailPoet tidak ditemui. Sila hubungi pentadbir.','Built by Neil Lock, CEO of Zinn Digital® Ltd'=>'Dibina oleh Neil Lock, Ketua Pegawai Eksekutif Zinn Digital® Ltd','Version %s'=>'Versi %s','Page Builder Sandwich website'=>'Laman web Page Builder Sandwich','Zinn Digital® website'=>'Laman web Zinn Digital®','Settings saved.'=>'Tetapan disimpan.','See the Pro plans and pricing'=>'Lihat pelan dan harga Pro','Front-end output'=>'Output front-end','Class name prefix'=>'Prefiks nama kelas','Every class name the plugin prints on your pages starts with this prefix, so the pages do not reveal which plugin built them. 1 to 8 lowercase letters or digits, starting with a letter.'=>'Setiap nama kelas yang dicetak oleh palam masuk pada halaman anda bermula dengan awalan ini, supaya halaman tidak mendedahkan palam masuk yang membina halaman tersebut. 1 hingga 8 huruf kecil atau digit, bermula dengan huruf.','Save'=>'Simpan','Beta updates'=>'Kemas kini beta','This site receives beta versions as updates.'=>'Tapak ini menerima versi beta sebagai kemas kini.','This site receives stable versions only.'=>'Laman web ini menerima versi stabil sahaja.','Change this on the Account page'=>'Tukar ini pada halaman Akaun','Beta versions are offered to licensed Pro installations that are connected to their account. Once connected, you can join from the Account page.'=>'Versi beta ditawarkan kepada pemasangan Pro berlesen yang disambungkan ke akaun mereka. Setelah disambungkan, anda boleh menyertai dari halaman Akaun.','The request converting this post stopped before it finished, so the post was skipped. Open it to convert it, or convert it again from here.'=>'Permintaan untuk menukar hantaran ini berhenti sebelum selesai, jadi hantaran tersebut dilangkau. Buka ia untuk menukarnya, atau tukar semula dari sini.','There is no backup of this post to restore.'=>'Tiada sandaran untuk hantaran ini untuk dipulihkan.','The converted content could not be saved.'=>'Kandungan yang telah ditukar tidak dapat disimpan.','Unknown error.'=>'Ralat tidak diketahui.','No legacy content has been checked yet.'=>'Tiada kandungan warisan yang telah disemak lagi.','Restoring legacy content: %1$d of %2$d posts.'=>'Memulihkan kandungan legasi: %1$d daripada %2$d hantaran.','Converting legacy content: %1$d of %2$d posts.'=>'Menukar kandungan lama: %1$d daripada %2$d hantaran.','Undo finished: %1$d restored, %2$d failed.'=>'Pembatalan selesai: %1$d dipulihkan, %2$d gagal.','Conversion finished: %1$d converted, %2$d unchanged, %3$d failed.'=>'Penukaran selesai: %1$d ditukar, %2$d tidak berubah, %3$d gagal.','Legacy content'=>'Kandungan lama','Pages made with earlier versions of Page Builder Sandwich are converted to blocks in the background. Every post is backed up first, so each conversion can be undone.'=>'Halaman yang dibuat dengan versi Page Builder Sandwich yang lebih awal ditukar kepada blok di latar belakang. Setiap siaran disandarkan terlebih dahulu, jadi setiap penukaran boleh diundur.','%d post still holds legacy content.'=>'%d hantaran masih mengekalkan kandungan lama.','%d post has a backup.'=>'%d hantaran mempunyai sandaran.','%d post could not be handled'=>'%d hantaran tidak dapat dikendalikan','Post %d'=>'Siaran %d','Conversion started. It continues in the background; you can leave this page.'=>'Penukaran dimulakan. Ia diteruskan di latar belakang; anda boleh meninggalkan halaman ini.','Convert legacy content'=>'Tukar kandungan legasi','Restore every converted post to its legacy content? Changes made to those posts since they were converted will be lost.'=>'Pulihkan setiap siaran yang ditukar kepada kandungan legasinya? Perubahan yang dibuat pada siaran tersebut sejak ia ditukar akan hilang.','Undo started. It continues in the background; you can leave this page.'=>'Pembatalan dimulakan. Ia diteruskan di latar belakang; anda boleh meninggalkan halaman ini.','Undo all conversions'=>'Batalkan semua penukaran','Shortcode tag'=>'Tag shortkod','Use letters, numbers, dashes and underscores only.'=>'Gunakan huruf, nombor, sempang dan garis bawah sahaja.','Attribute name'=>'Nama atribut','Add attribute'=>'Tambah atribut','Content'=>'Kandungan','Shortcode'=>'Kod pendek','Choose a shortcode tag in the block settings.'=>'Pilih tag kod pendek dalam tetapan blok.','The "%s" control from the old editor is not available in the block editor. Enter the value as text.'=>'Kawalan "%s" daripada editor lama tidak tersedia dalam editor blok. Masukkan nilai sebagai teks.','Choose image'=>'Pilih imej','Choose file'=>'Pilih fail','— Default —'=>'— Lalai —','Advanced styling'=>'Gaya lanjutan','Inline CSS'=>'CSS Sebaris','CSS declarations, for example: min-height: 380px; background-color: #333'=>'Pengisytiharan CSS, contohnya: min-height: 380px; background-color: #333','Effects (legacy classes)'=>'Kesan (kelas warisan)','Space-separated effect names carried over from older versions, for example: hover-shadow'=>'Nama kesan yang dipisahkan oleh ruang dibawa dari versi lama, contohnya: hover-shadow','Row'=>'Baris','Width'=>'Lebar','Content width'=>'Lebar kandungan','Full width'=>'Lebar penuh','Full width, content kept in the middle'=>'Lebar penuh, kandungan dikekalkan di tengah','Link'=>'Pautkan','Link address'=>'Alamat pautan','Open in a new tab'=>'Buka dalam tab baharu','Link relationship'=>'Hubungan pautan','Alignment'=>'Jajaran','None'=>'Tiada','Left'=>'Kiri','Centre'=>'Pusat','Right'=>'Kanan','Button text'=>'Teks butang','Add text…'=>'Tambah teks...','Icon'=>'Ikon','SVG markup'=>'Penanda SVG','Scripts, links and external references are removed before the icon is shown.'=>'Skrip, pautan dan rujukan luar dialih keluar sebelum ikon dipaparkan.','Accessible label'=>'Label boleh akses','Leave empty for a decorative icon.'=>'Biarkan kosong untuk ikon hiasan.','Paste SVG markup in the block settings.'=>'Tampal penanda markup SVG dalam tetapan blok.','New setting name'=>'Nama tetapan baharu','For example: title or text'=>'Sebagai contoh: tajuk atau teks','Add setting'=>'Tambah tetapan','Widget'=>'Widget','Choose a widget'=>'Pilih widget','Widget area'=>'Kawasan widget','Choose a widget area'=>'Pilih kawasan widget','This image has no width and height, so the page will jump when it loads. Choose it from the Media Library, or set its width and height.'=>'Imej ini tidak mempunyai lebar dan ketinggian, jadi halaman akan melompat apabila ia dimuatkan. Pilih imej tersebut daripada Pustaka Media, atau tetapkan lebar dan ketinggiannya.','This video is not from the Media Library, so its size is unknown and the page will jump when it loads. Upload it to the Media Library instead.'=>'Video ini bukan dari Pustaka Media, jadi saiznya tidak diketahui dan halaman akan beralih apabila ia dimuatkan. Muat naik ke Pustaka Media sebagai gantinya.','An image, video or frame in this HTML has no width and height, so the page will jump when it loads. Add width and height attributes to it.'=>'Satu imej, video atau bingkai dalam HTML ini tiada lebar dan ketinggian, jadi halaman akan beralih apabila ia dimuatkan. Tambahkan atribut lebar dan ketinggian kepadanya.','This embed resizes itself after it loads, which moves the content below it. Give it room or place it lower on the page.'=>'Benamkan ini mengubah saiz sendiri selepas ia dimuatkan, yang mengalihkan kandungan di bawahnya. Berikannya ruang atau letakkannya lebih rendah pada halaman.','Layout shift'=>'Perubahan reka letak','Heading'=>'Tajuk','Text'=>'Teks','Style'=>'Gaya','Plain'=>'Biasa','Accent'=>'Aksen','No languages to switch between. The switcher appears when a translation plugin lists two or more languages.'=>'Tiada bahasa untuk ditukar ganti. Penukar dipaparkan apabila palam masuk terjemahan menyenaraikan dua bahasa atau lebih.','Switcher'=>'Penukar','Show the current language'=>'Tunjukkan bahasa semasa','%s is also editing this page. Saving may overwrite their changes.'=>'%s juga sedang mengedit halaman ini. Menyimpan mungkin akan menimpa perubahan mereka.','Block library'=>'Pustaka blok','Layers'=>'Lapisan','Close panel'=>'Tutup panel','Page canvas'=>'Kain rentang halaman','Revisions'=>'Semakan','Block settings'=>'Tetapan sekatan','Add block: %s'=>'Tambah blok: %s','(no title)'=>'(tiada tajuk)','Open in Studio: %s'=>'Buka dalam Studio: %s','Undo'=>'Buat asal','Redo'=>'Buat semula','Show or hide layers'=>'Tunjuk atau sembunyikan lapisan','Show or hide the block library'=>'Tunjukkan atau sembunyikan pustaka blok','Show revisions'=>'Paparkan semakan','Open the normal editor'=>'Buka penyunting biasa','Keyboard shortcuts'=>'Pintasan papan kekunci','Preview: desktop'=>'Pratonton: desktop','Preview: tablet'=>'Pratonton: tablet','Preview: mobile'=>'Pratonton: mudah alih','Copy style of the selected block'=>'Salin gaya blok yang dipilih','Paste style onto the selected block'=>'Tampal gaya pada blok yang dipilih','Copy the selected section'=>'Salin bahagian yang dipilih','Paste a copied section'=>'Tampal bahagian yang disalin','Turn off safe mode'=>'Matikan mod selamat','Turn on safe mode (other plugins off, for you, in Studio only)'=>'Hidupkan mod selamat (palam lain dimatikan, untuk anda, dalam Studio sahaja)','Published'=>'Diterbitkan','Scheduled'=>'Berjadual','Pending review'=>'Menunggu semakan','Private'=>'Peribadi','Draft'=>'Draf','All changes saved'=>'Semua perubahan disimpan','Saving…'=>'Sedang menyimpan…','Autosaving…'=>'Menyimpan automatik…','Unsaved changes'=>'Perubahan belum disimpan','autosaved'=>'disimpan automatik','Desktop preview'=>'Pratonton desktop','Tablet preview'=>'Pratonton tablet','Mobile preview'=>'Pratonton mudah alih','Studio toolbar'=>'Bar alat Studio','Back to the normal editor'=>'Kembali ke editor biasa','Page title'=>'Tajuk halaman','Preview width'=>'Lebar pratonton','Command palette'=>'Palet arahan','View page (opens in a new tab)'=>'Lihat halaman (buka dalam tab baharu)','Update'=>'Kemas kini','Save draft'=>'Simpan draf','Publish'=>'Terbitkan','Restore unsaved changes?'=>'Pulihkan perubahan yang belum disimpan?','This page has changes that were never saved. They were kept in this browser:'=>'Halaman ini mempunyai perubahan yang tidak pernah disimpan. Perubahan tersebut disimpan dalam pelayar ini:','This page has a newer autosave than the saved version:'=>'Halaman ini mempunyai simpanan automatik yang lebih baharu daripada versi yang disimpan:','Restore unsaved changes'=>'Pulihkan perubahan yang belum disimpan','Discard'=>'Buang','Revisions could not be loaded.'=>'Semakan tidak dapat dimuatkan.','Revision restored. Save to keep it, or undo to go back.'=>'Semakan dipulihkan. Simpan untuk mengekalkannya, atau batalkan untuk kembali.','Close revisions'=>'Tutup semakan','No revisions yet. Each save makes one.'=>'Belum ada semakan lagi. Setiap simpanan menghasilkan satu.','Revision from %s'=>'Semakan daripada %s','Restore this revision'=>'Pulihkan semakan ini','Cancel'=>'Batal','Safe mode could not be changed.'=>'Mod selamat tidak dapat ditukar.','Safe mode is on.'=>'Mod selamat diaktifkan.','%d other plugin is switched off, for you and in Sandwich Studio only. The live site and other users are not affected.'=>'%d palam lain dimatikan, untuk anda dan di Sandwich Studio sahaja. Laman web langsung dan pengguna lain tidak terjejas.','Safe mode: switch other plugins off in Studio, for you only'=>'Mod selamat: matikan palam tara lain dalam Studio, untuk anda sahaja','Safe mode'=>'Mod selamat','Save your changes.'=>'Simpan perubahan anda.','Undo your last change.'=>'Batalkan perubahan terakhir anda.','Redo your last undo.'=>'Buat semula tindakan undo anda yang terakhir.','Show or hide the layers panel.'=>'Tunjuk atau sembunyikan panel lapisan.','Display these keyboard shortcuts.'=>'Papar pintasan papan kekunci ini.','Select a block first.'=>'Pilih blok terlebih dahulu.','Style copied. Paste it onto any block, on this site or another.'=>'Gaya disalin. Tampalkannya pada mana-mana blok, di tapak ini atau yang lain.','The browser refused to copy.'=>'Pelayar web enggan menyalin.','Section copied. Paste it into any page, on this site or another.'=>'Bahagian disalin. Tampalkannya pada mana-mana halaman, di tapak web ini atau yang lain.','The clipboard does not hold a style copied from Sandwich Studio.'=>'Papan klip tidak mengandungi gaya yang disalin daripada Sandwich Studio.','Style pasted onto %d block.'=>'Gaya ditampal pada %d blok.','That style does not fit the selected block.'=>'Gaya tersebut tidak sepadan dengan blok yang dipilih.','The clipboard does not hold a copied section.'=>'Papan klip tidak mengandungi bahagian yang disalin.','Section pasted.'=>'Bahagian telah dilekatkan.','Paste style'=>'Tampal gaya','Paste section'=>'Tampal bahagian','Press Ctrl+V (or Cmd+V on a Mac) here to paste'=>'Tekan Ctrl+V (atau Cmd+V pada Mac) di sini untuk melekat','Copy style'=>'Salin gaya','Copy section'=>'Salin bahagian','Edit in Sandwich Studio'=>'Sunting dalam Sandwich Studio','Saving failed. Check your connection and try again; your changes are kept in this browser.'=>'Penyimpanan gagal. Semak sambungan anda dan cuba lagi; perubahan anda disimpan dalam pelayar ini.','Published.'=>'Diterbitkan.','Saved.'=>'Disimpan.','block titleButton link'=>'Pautan butang','block descriptionA link styled as a button.'=>'Pautan yang digayakan sebagai butang.','block keywordbutton'=>'butang','block keywordlink'=>'pautan','block keywordcall to action'=>'seruan bertindak','block titleColumn'=>'Lajur','block descriptionA column inside a row. It can hold any block.'=>'Kolaj di dalam baris. Ia boleh memegang sebarang blok.','block keywordcolumn'=>'kolum','block keywordlayout'=>'susunan','block titleLanguage switcher (sample)'=>'Pertukar bahasa (sampel)','block descriptionLists the site\'s languages from the translation plugin, when one is active. It renders nothing otherwise.'=>'Senaraikan bahasa tapak daripada palam pelantar terjemahan, apabila salah satu aktif. Ia tidak memaparkan apa-apa jika sebaliknya.','block keywordlanguage'=>'Bahasa','block keywordswitcher'=>'penukar','block titleSample content'=>'Kandungan sampel','block descriptionA heading and a paragraph, rendered with neutral class names. It is the reference block for the translation contract.'=>'Tajuk dan satu perenggan, direka bentuk dengan nama kelas neutral. Ia adalah blok rujukan untuk kontrak terjemahan.','block keywordsample'=>'sampel','block keywordtext'=>'teks','block titleIcon'=>'Ikon','block descriptionAn SVG icon. The markup is cleaned before it is shown.'=>'Ikon SVG. Markup dibersihkan sebelum dipaparkan.','block keywordicon'=>'ikon','block keywordsvg'=>'svg','block titleRow'=>'Baris','block descriptionA row of columns. Stays readable if the plugin is ever turned off.'=>'Satu baris lajur. Kekal boleh dibaca jika palam masuk dimatikan pada bila-bila masa.','block keywordrow'=>'baris','block keywordcolumns'=>'lajur','block titleShortcode (add-on)'=>'Kod pendek (tambahan)','block descriptionA shortcode from an add-on written for the classic Page Builder Sandwich editor, with the settings the add-on declared.'=>'Kod pendek daripada add-on yang ditulis untuk penyunting klasik Page Builder Sandwich, berserta tetapan yang diisytiharkan oleh add-on tersebut.','block keywordshortcode'=>'kod pendek','block keywordadd-on'=>'tambahan','block titleWidget area'=>'Kawasan widget','block descriptionShows the widgets in one of the theme\'s widget areas.'=>'Menunjukkan widget dalam salah satu kawasan widget tema tersebut.','block keywordsidebar'=>'sisi bar','block keywordwidget area'=>'kawasan widget','block titleWidget'=>'Widget','block descriptionShows one of the site\'s registered classic widgets.'=>'Menunjukkan salah satu widget klasik tapak yang berdaftar.','block keywordwidget'=>'widget']];